import {growthReady} from './growth.js?v=simulation15';
import {PLOTS,DESTINATIONS,ensureCounty,buyPlot,startPlot,collectPlot,plotCost,countyBoard,acceptContract,deliverContract,abandonContract,contractStatus} from './county-sim.js?v=simulation15';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const amounts=o=>Object.entries(o).map(([k,v])=>v+' '+k).join(' + ');
export function installCountyUI({state,save,modal,toast,walk,work,stationFor,refresh}){
 function panel(title,body){modal('<span class="service-tag">MEADOW COUNTY</span><h2>'+title+'</h2>'+body+'<div class="choice county-footer"><button onclick="openRegionalMap()">Regional farms →</button><button onclick="openCountyMap()">County map</button><button onclick="openCountyContracts()">Village requests</button><button onclick="openCountyEstate()">Your estate</button></div>');}
 const contractCard=r=>'<article class="county-card"><b>'+esc(r.buyer)+'</b><p>'+r.qty+' '+esc(r.good)+' → <strong>'+r.reward+' farm coins</strong></p><small>'+esc(contractStatus(state,r))+' · due farm day '+r.dueDay+'</small>'+(contractStatus(state,r)==='active'?'<div class="choice"><button class="primary" onclick="deliverCounty(\''+r.id+'\')">Walk to depot & deliver</button><button onclick="cancelCounty(\''+r.id+'\')">Cancel</button></div>':'')+'</article>';
 window.openCountyMap=()=>{const county=ensureCounty(state);const markers=DESTINATIONS.map((d,i)=>'<button class="county-pin '+(d.id==='farm'?'home':'')+'" style="left:'+((d.x+96)/204*100)+'%;top:'+((d.z+84)/168*100)+'%" onclick="openCountyPlace(\''+d.id+'\')" aria-label="'+esc(d.name)+'"><span>'+(i+1)+'</span></button>').join('');
 panel('A bigger little world.','<p>Follow the county roads from your original farm to the village, delivery depot and new land. Choose a place on the map to visit or inspect.</p><div class="county-map" role="group" aria-label="Meadow County map"><svg viewBox="0 0 204 168" aria-hidden="true" preserveAspectRatio="none"><path d="M48 8V160M160 8V160M48 48H160M48 128H160M24 48H48M24 88H48M24 112H48M24 20V128M160 146H195" fill="none" stroke="#d8c399" stroke-width="4"/><path d="M48 90H160" stroke="#ebe0c1" stroke-width="2"/></svg>'+markers+'</div><div class="county-legend">'+DESTINATIONS.map((d,i)=>'<button onclick="openCountyPlace(\''+d.id+'\')">'+(i+1)+' · '+esc(d.name)+'</button>').join('')+'</div><p>'+Object.keys(county.plots).length+' / '+PLOTS.length+' plots owned · '+county.deliveries+' deliveries · Reputation '+county.reputation+'</p><p class="asset-note">Local simulation · no real money. Progress stays in this browser. County traffic follows ambient delivery routes.</p>');};
 window.openCountyPlace=id=>{if(PLOTS.some(p=>p.id===id))return window.openCountyPlot(id);const d=DESTINATIONS.find(x=>x.id===id);if(!d)return;if(id==='village'||id==='depot')return window.openCountyContracts();panel(esc(d.name),'<p>'+(id==='farm'?'Your original farm, animals and stables.':id==='racegate'?'The county entrance connects to your existing racing stable.':'Trade supplies through the existing Meadow Exchange order book.')+'</p><button class="primary" onclick="walkCounty(\''+id+'\')">Walk here</button>'+(id==='supply'?'<button onclick="visitExchange()">Open exchange</button>':id==='racegate'?'<button onclick="enterCountyRace()">Walk to Meadow Park & enter</button>':''));};
 window.walkCounty=id=>{const d=DESTINATIONS.find(x=>x.id===id);if(!d)return;document.querySelector('dialog').close();walk(d.approach.x,d.approach.z,'Walk to '+d.name,()=>{if(id==='farm')toast('Welcome back to your farm.');else window.openCountyPlace(id);});};
 window.enterCountyRace=()=>{document.querySelector('dialog').close();const d=DESTINATIONS.find(x=>x.id==='racegate');walk(d.approach.x,d.approach.z,'Walk to Meadow Park',()=>{save();location.href='racing.html';});};
 window.openCountyEstate=()=>{const c=ensureCounty(state);panel('Build your estate.','<p>Buy neighbouring land with available farm coins. Each property adds a production business alongside your original specialist farm. No daily rent or automatic spending.</p>'+PLOTS.map(p=>{const r=c.plots[p.id];return '<article class="county-card"><h3>'+p.name+'</h3><p>'+(r?(r.job?(growthReady(r.job,state.day)?'Ready to collect':'Producing · ready farm day '+r.job.readyDay):'Owned · ready for a new cycle'):p.price+' farm coins · available')+'</p><button onclick="openCountyPlot(\''+p.id+'\')">Inspect property →</button></article>';}).join(''));};
 window.openCountyPlot=id=>{if(id==='county-mill'&&ensureCounty(state).plots[id])return window.openProduction('county');const p=PLOTS.find(x=>x.id===id);if(!p)return;const r=ensureCounty(state).plots[id];panel(p.name,'<p>'+(p.kind==='field'?'Grow maize in a dedicated northern field.':p.kind==='orchard'?'Establish fruit trees. Seeds are only needed for the first crop; later crops use water.':p.kind==='well'?'Use power to run the county water pump.':'Turn maize into grain feed at your own mill.')+'</p><p><b>'+amounts(plotCost(state,id))+' → '+amounts(p.output)+'</b><br>'+p.days+' farm day'+(p.days===1?'':'s')+' per cycle. Growth also continues in real time while away. Collection is manual. Orchards have permanent apple, pear, orange and plum trees; fruit regrows each cycle.</p>'+(r?'<p>Owned since day '+r.boughtDay+' · '+r.cycles+' completed cycles</p>'+(r.job?'<p>'+(growthReady(r.job,state.day)?'Your production is ready.':'Ready on farm day '+r.job.readyDay)+'</p><button class="primary" onclick="countyPlotAction(\''+id+'\',\'collect\')" '+(!growthReady(r.job,state.day)?'disabled':'')+'>Walk here & collect '+amounts(r.job.output)+'</button>':'<button class="primary" onclick="countyPlotAction(\''+id+'\',\'start\')">Walk here & start production</button>'):'<p>Purchase price: <b>'+p.price+' available farm coins</b>. The plot stays yours.</p><button class="primary" onclick="countyPlotAction(\''+id+'\',\'buy\')">Walk here & buy property</button>')+'<button onclick="walkCounty(\''+id+'\')">Visit property</button><p>Materials and coins are checked when your queued action finishes. Supplies reserved on the exchange cannot be used.</p>');};
 window.countyPlotAction=(id,action)=>{const p=PLOTS.find(x=>x.id===id),fn={buy:buyPlot,start:startPlot,collect:collectPlot}[action];if(!p||!fn)return;work(stationFor(id),()=>{try{fn(state,id);save();refresh();toast(p.name+': '+({buy:'property purchased',start:'production started',collect:'produce collected'}[action])+'.');}catch(e){toast(e.message);}},({buy:'Buy ',start:'Start ',collect:'Collect from '}[action])+p.name);};
 window.openCountyContracts=()=>{const c=ensureCounty(state),active=c.contracts.filter(r=>contractStatus(state,r)==='active');panel('The village needs you.','<p>Deliver produce to the depot for farm coins and reputation. Three new requests appear each farm day. Up to three may be active at once.</p><div class="choice"><button onclick="walkCounty(\'village\')">Visit co-op</button><button onclick="walkCounty(\'depot\')">Walk to depot</button></div><h3>Your deliveries · '+active.length+' / 3</h3>'+(active.map(contractCard).join('')||'<p>No active deliveries.</p>')+'<h3>Today’s requests</h3>'+countyBoard(state).map(r=>'<article class="county-card"><b>'+esc(r.buyer)+'</b><p>'+r.qty+' '+esc(r.good)+' → '+r.reward+' farm coins</p><small>Deadline: farm day '+r.dueDay+'</small><button class="primary" onclick="takeCounty(\''+r.id+'\')" '+(r.status!=='available'?'disabled':'')+'>'+(r.status==='available'?'Accept request':esc(r.status))+'</button></article>').join('')+'<h3>Delivery record</h3>'+c.contracts.slice(-6).reverse().map(r=>'<p>'+esc(r.buyer)+' · '+esc(contractStatus(state,r))+' · '+r.qty+' '+esc(r.good)+'</p>').join('')+'<p>Acceptance reserves no goods. Deliver before the deadline using available stock; rewards are paid once on handover. Cancelling has no penalty.</p>');};
 window.takeCounty=id=>{try{acceptContract(state,id);save();window.openCountyContracts();toast('Request accepted. Take the goods to the delivery depot.');}catch(e){toast(e.message);}};
 window.cancelCounty=id=>{try{abandonContract(state,id);save();window.openCountyContracts();}catch(e){toast(e.message);}};
 window.deliverCounty=id=>work(stationFor('depot'),()=>{try{const r=deliverContract(state,id);save();toast('Delivered to '+r.buyer+' · +'+r.reward+' coins · +5 reputation.');}catch(e){toast(e.message);}},'Deliver '+id);
}
